const $=s=>document.querySelector(s);const icons={bench:'▦',library:'◈',experiments:'⚗',analysis:'⌁',bom:'☷'};
const catalog=[{type:'source',name:'532 nm laser',part:'Ideal Gaussian source',brand:'Ideal',f:0,power:5,waist:1.2},{type:'lens',name:'Achromatic doublet',part:'AC254-050-A',brand:'Thorlabs',f:50},{type:'lens',name:'Achromatic doublet',part:'AC254-200-A',brand:'Thorlabs',f:200},{type:'aperture',name:'Adjustable iris',part:'SM1D12',brand:'Thorlabs',aperture:5},{type:'mirror',name:'Dielectric mirror',part:'Ideal mirror',brand:'Ideal',f:0},{type:'camera',name:'CMOS camera',part:'Generic monochrome',brand:'Ideal',exposure:10},{type:'screen',name:'Beam profiler',part:'Virtual instrument',brand:'Ideal'},{type:'filter',name:'Neutral density filter',part:'Ideal ND filter',brand:'Ideal',transmission:50}];
const presets={expander:[{...catalog[0],x:90},{...catalog[1],x:230},{...catalog[2],x:480},{...catalog[6],x:710}],focus:[{...catalog[0],x:90},{...catalog[2],x:350},{...catalog[6],x:550}],imaging:[{...catalog[0],name:'Resolution target',type:'image',x:80},{...catalog[1],x:230},{...catalog[3],x:330},{...catalog[2],x:530},{...catalog[5],x:730}]};
let state={items:structuredClone(presets.expander).map((c,i)=>({...c,id:i+1,y:245})),selected:2,mode:'Gaussian beam',running:true,grid:true,zoom:1,tab:'Profile',page:'bench',query:'',category:'All',wavelength:532,title:'Keplerian beam expander',undo:[]};let customImage=null;let uid=10;let noticeTimer;
function checkpoint(){state.undo.push(JSON.stringify(state.items));if(state.undo.length>30)state.undo.shift()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function optic(c,small=false){let color=c.type==='source'?'#bafa74':c.type==='camera'||c.type==='screen'?'#bdacff':'#8abfff';let shape=c.type==='lens'?`<ellipse cx="30" cy="30" rx="9" ry="24" fill="${color}33" stroke="${color}" stroke-width="2"/><path d="M30 6v48" stroke="${color}55"/>`:c.type==='source'||c.type==='image'?`<rect x="8" y="15" width="39" height="30" rx="5" fill="#393e3e" stroke="#768178"/><path d="M16 21v18m6-18v18m6-18v18" stroke="#778573"/><rect x="47" y="24" width="9" height="12" rx="2" fill="${color}"/>`:c.type==='mirror'?`<path d="M12 50L48 10" stroke="#8abfff" stroke-width="6"/>`:c.type==='aperture'||c.type==='filter'?`<rect x="22" y="5" width="16" height="50" rx="4" fill="#555b63" stroke="#adb6c4"/><path d="M22 25h16v10H22" fill="#11151b"/>`:`<rect x="15" y="7" width="30" height="46" rx="5" fill="#373441" stroke="${color}"/><rect x="21" y="15" width="18" height="30" rx="2" fill="${color}22"/><circle cx="30" cy="30" r="6" fill="${color}88"/>`;return `<svg viewBox="0 0 60 60" width="${small?38:60}" height="${small?38:60}" aria-hidden="true">${shape}</svg>`}
function render(){const selected=state.items.find(c=>c.id===state.selected);$('#app').innerHTML=`<header><a class="brand" href="#" aria-label="OptiBench home"><span class="brand-mark">⦶</span>opti<span>bench</span><small>LAB</small></a><div class="project-label"><span class="folder">▱</span> My workspace <span class="slash">/</span><button id="rename">${escapeHtml(state.title)} <span class="chevron">⌄</span></button><span class="saved">Local session</span></div><div class="header-actions"><button id="save">↧ <span>Save project</span></button><button class="avatar" title="Local workspace">AP</button></div></header><div class="layout"><nav class="rail">${Object.entries(icons).map(([k,v])=>`<button title="${k}" data-page="${k}" class="${state.page===k?'active':''}"><b>${v}</b><span>${({bench:'Bench',library:'Library',experiments:'Templates',analysis:'Analysis',bom:'Parts'})[k]}</span></button>`).join('')}<div class="rail-bottom"><button id="help"><b>?</b><span>Guide</span></button></div></nav><aside class="library"><div class="panel-heading"><h2>Component library</h2><span class="count">${catalog.length}</span></div><div class="search"><span>⌕</span><input id="search" placeholder="Search components…" value="${escapeHtml(state.query)}"><kbd>⌘ K</kbd></div><div class="categories">${['All','Sources','Optics','Detectors'].map(c=>`<button data-category="${c}" class="${state.category===c?'selected':''}">${c}</button>`).join('')}</div><div class="catalog-caption">COMPONENTS <span>＋</span></div><div id="catalog"></div><div class="library-foot"><span>⊕</span><div>Built for the real bench<small>Reference parts & ideal components</small></div></div></aside><main><div class="bench-toolbar"><div><span class="mini-label">EXPERIMENT 01</span><h1>${escapeHtml(state.title)}</h1></div><div class="toolbar-buttons"><button id="undo" title="Undo">↶</button><button id="load" title="Open project">▱</button><span class="divider"></span><button id="run" class="run ${state.running?'':'paused'}">${state.running?'Ⅱ Pause':'▶ Run simulation'}</button></div></div><div class="modebar"><div class="mode-select"><span class="green-dot"></span><select id="mode">${['Gaussian beam','Geometrical optics','Fourier optics'].map(v=>`<option ${v===state.mode?'selected':''}>${v}</option>`).join('')}</select><span class="pill">PARAXIAL</span></div><div class="canvas-controls"><button id="grid" class="${state.grid?'on':''}" title="Toggle grid">▦</button><button id="zoomout" title="Zoom out">−</button><span id="zoomlabel">${Math.round(state.zoom*100)}%</span><button id="zoomin" title="Zoom in">＋</button><button id="fit" title="Fit bench">⛶</button></div></div><div class="bench-stage"><svg id="bench" viewBox="0 0 820 470" aria-label="Interactive optical bench"></svg><div class="bench-tag">TOP VIEW <span>XY</span></div><div class="bench-hint">Drag to position <i>·</i> Select to inspect <i>·</i> Click a library part to add</div><div class="scale">100 mm<div></div></div></div><section class="results"><div class="result-heading"><div class="result-tabs">${['Profile','Beam envelope','Camera image'].map(v=>`<button data-tab="${v}" class="${state.tab===v?'active':''}">${v}</button>`).join('')}</div><span class="live"><span class="green-dot"></span> ${state.running?'Live simulation':'Paused'}</span></div><div id="results-body"></div></section><footer><span><span class="green-dot"></span> ${state.items.length} components <i>·</i> Units: mm</span><span id="status-detail">Paraxial model <i>·</i> λ ${state.wavelength} nm</span><span>OptiBench <b>0.1</b></span></footer></main><aside class="inspector"><div class="panel-heading"><h2>Inspector</h2><span>⚙</span></div><div id="inspector-body"></div><div class="inspector-bottom"><span>ⓘ</span> First-order optical model. Reference part specifications require verification before purchasing.</div></aside></div><div id="toast" role="status"></div><dialog id="modal"><div id="modal-content"></div></dialog><input type="file" id="project-file" accept="application/json" hidden><input type="file" id="image-file" accept="image/*" hidden>`;renderCatalog();renderBench();renderInspector(selected);renderResults();bind()}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderCatalog(){const filtered=catalog.filter(c=>(state.category==='All'||(state.category==='Sources'&&['source','image'].includes(c.type))||(state.category==='Optics'&&['lens','mirror','aperture','filter'].includes(c.type))||(state.category==='Detectors'&&['camera','screen'].includes(c.type)))&&(c.name+' '+c.part+' '+c.brand).toLowerCase().includes(state.query.toLowerCase()));$('#catalog').innerHTML=filtered.length?filtered.map(c=>`<button draggable="true" class="component-card" data-add="${catalog.indexOf(c)}"><span class="component-icon">${optic(c,true)}</span><span class="component-text"><strong>${c.name}</strong><small>${c.part}</small><span>${c.brand}${c.f?' <i>·</i> f = '+c.f+' mm':''}</span></span><span class="add-sign">＋</span></button>`).join(''):'<p class="empty">No matching components.</p>';document.querySelectorAll('[data-add]').forEach(el=>{el.onclick=()=>add(+el.dataset.add);el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.add)})}
function simulate(items=state.items){const sorted=[...items].sort((a,b)=>a.x-b.x);const source=sorted.find(c=>['source','image'].includes(c.type));let w=source?.waist||1.2;const lambda=state.wavelength/1e6;let q={re:0,im:Math.PI*w*w/lambda};let power=source?.power||5;let prev=source?.x||0;let points=[{x:prev,w}];let rays=[{x:prev,h:w,a:0}];let h=w,a=0;let blocked=false;for(let x=prev+2;x<=800;x+=2){q.re+=2;h+=a*2;for(const c of sorted.filter(c=>c.x>x-2&&c.x<=x&&!['source','image'].includes(c.type))){if(c.type==='lens'){const f=c.f||1;const den=(1-q.re/f)**2+(q.im/f)**2;q={re:(q.re*(1-q.re/f)-q.im*q.im/f)/den,im:q.im/den};a-=h/f}if(c.type==='filter')power*=c.transmission/100;if(c.type==='aperture'){let here=Math.sqrt(lambda/Math.PI*(q.re*q.re+q.im*q.im)/q.im);power*=1-Math.exp(-2*((c.aperture||5)/2)**2/here**2)}if(c.type==='mirror')blocked=true}w=Math.sqrt(Math.max(0,lambda/Math.PI*(q.re*q.re+q.im*q.im)/q.im));points.push({x,w:blocked?0:w});rays.push({x,h:blocked?0:Math.abs(h),a});}const detector=[...sorted].reverse().find(c=>['camera','screen'].includes(c.type));const end=points.reduce((p,c)=>Math.abs(c.x-(detector?.x||780))<Math.abs(p.x-(detector?.x||780))?c:p);return {points,rays,w:end.w,power:blocked?0:power,source,detector,mag:end.w/(source?.waist||1.2)}}
let lastResult;function renderBench(){const sim=state.running?simulate():lastResult||simulate();if(state.running)lastResult=sim;const cy=245;const points=state.mode==='Geometrical optics'?sim.rays.map(p=>({x:p.x,w:p.h})):sim.points;const scale=8;const path=points.map((p,i)=>`${i?'L':'M'}${p.x},${cy-Math.min(p.w*scale,170)}`).join(' ')+points.slice().reverse().map(p=>`L${p.x},${cy+Math.min(p.w*scale,170)}`).join(' ')+'Z';$('#bench').innerHTML=`<defs><pattern id="dots" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r="1.3" fill="#454b4c"/></pattern><linearGradient id="beamfill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#bafa74" stop-opacity=".28"/><stop offset=".5" stop-color="#bafa74" stop-opacity=".09"/><stop offset="1" stop-color="#bafa74" stop-opacity=".28"/></linearGradient></defs><rect width="820" height="470" fill="${state.grid?'url(#dots)':'#20242a'}"/><g transform="translate(${410*(1-state.zoom)},${235*(1-state.zoom)}) scale(${state.zoom})"><path d="M35 ${cy}H795" stroke="#525a58" stroke-dasharray="3 7"/><path d="${path}" fill="url(#beamfill)" stroke="#bafa74" stroke-width="1.4" opacity="${state.running?1:.4}"/><path d="M${sim.source?.x||0} ${cy}H800" stroke="#cbfa8e" stroke-width="1" opacity=".55"/>${[100,200,300,400,500,600,700].map(x=>`<text x="${x}" y="430" fill="#92989f" text-anchor="middle" font-size="11">${x}</text><path d="M${x} 413v5" stroke="#727a83"/>`).join('')}${state.items.map((c,i)=>`<g data-component="${c.id}" transform="translate(${c.x},${c.y})" class="bench-component" tabindex="0" role="button" aria-label="${escapeHtml(c.name)}"><rect x="-32" y="-43" width="64" height="86" rx="8" fill="${c.id===state.selected?'#ffffff05':'transparent'}" stroke="${c.id===state.selected?'#bafa74':'transparent'}" stroke-dasharray="4 3"/><svg x="-30" y="-30" width="60" height="60" viewBox="0 0 60 60">${optic(c).match(/<svg[^>]*>([\s\S]*)<\/svg>/)[1]}</svg><text x="0" y="-62" fill="${c.id===state.selected?'#c0f58a':'#dfe2e6'}" font-size="12" text-anchor="middle">${c.type==='lens'?'f = '+c.f+' mm':c.type==='source'?state.wavelength+' nm':c.type==='screen'?'Beam profiler':c.type==='camera'?'Camera':escapeHtml(c.name)}</text><rect x="-13" y="57" width="26" height="21" rx="5" fill="${c.id===state.selected?'#bafa74':'#343940'}"/><text x="0" y="71" text-anchor="middle" font-size="11" fill="${c.id===state.selected?'#182210':'#b9bfc8'}">${String(i+1).padStart(2,'0')}</text></g>`).join('')}<path d="M230 350v9h250v-9" stroke="#6e7783" fill="none"/><text x="355" y="382" fill="#a2a9b3" font-size="12" text-anchor="middle">${state.items.filter(c=>c.type==='lens').length>1?Math.round(Math.abs(state.items.filter(c=>c.type==='lens')[1].x-state.items.filter(c=>c.type==='lens')[0].x))+' mm lens separation':'Optical axis →'}</text></g>`;$('#bench').querySelectorAll('[data-component]').forEach(el=>{el.onpointerdown=e=>{e.preventDefault();checkpoint();state.selected=+el.dataset.component;let item=state.items.find(c=>c.id===state.selected);let originalX=item.x;const move=ev=>{const matrix=$('#bench').getScreenCTM().inverse();const point=new DOMPoint(ev.clientX,ev.clientY).matrixTransform(matrix);item.x=Math.round(Math.max(40,Math.min(780,(point.x-410*(1-state.zoom))/state.zoom)));renderBench();renderInspector(item);renderResults()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',()=>{window.removeEventListener('pointermove',move);renderBench();if(innerWidth<=1000&&Math.abs(item.x-originalX)<3){modal('Component inspector','<div id="inspector-body"></div>');document.querySelector('.inspector #inspector-body').id='hidden-inspector-body';renderInspector(item)}},{once:true});renderInspector(item);renderBench()};el.onkeydown=e=>{if(e.key==='Enter'){state.selected=+el.dataset.component;render()}}})}
function renderInspector(c){if(!c){$('#inspector-body').innerHTML='<p class="empty">Select a component on the bench.</p>';return}$('#inspector-body').innerHTML=`<div class="selected-component"><div class="selected-icon">${optic(c)}</div><span class="eyebrow">${c.brand.toUpperCase()}</span><h3>${c.name}</h3><p>${c.part}</p><span class="part-tag">${c.brand==='Ideal'?'IDEAL COMPONENT':'REFERENCE COMPONENT'}</span></div><div class="inspector-section"><h4>Position <span>⌖</span></h4><div class="two-fields"><label>X position<div class="input-unit"><input data-prop="x" type="number" value="${c.x}" min="40" max="780"><span>mm</span></div></label><label>Y offset<div class="input-unit"><input type="number" value="0" disabled><span>mm</span></div></label></div><p class="field-note">Centered on the optical axis</p></div><div class="inspector-section"><h4>Optical properties <span>◇</span></h4>${c.type==='lens'?field('Nominal focal length','f',c.f,'mm',1,1000)+`<div class="spec-row"><span>Diameter</span><b>25.4 mm</b></div><div class="spec-row"><span>Model</span><b>Thin lens</b></div><div class="spec-row"><span>Coating model</span><b>Ideal / lossless</b></div>`:c.type==='source'||c.type==='image'?field('Beam waist (1/e² radius)','waist',c.waist||1.2,'mm',.01,20)+field('Optical power','power',c.power||5,'mW',.01,1000)+`<label class="full-field">Wavelength<div class="input-unit"><input id="wavelength" type="number" value="${state.wavelength}" min="200" max="2000"><span>nm</span></div></label>${c.type==='image'?'<button id="upload-image" class="full-button">↑ Upload source image</button>':''}`:c.type==='aperture'?field('Clear aperture','aperture',c.aperture,'mm',.01,25):c.type==='filter'?field('Transmission','transmission',c.transmission,'%',0,100):c.type==='camera'?field('Exposure','exposure',c.exposure,'ms',.01,1000):c.type==='mirror'?'<p class="field-note">Mirror terminates the axial model. Folded paths are not simulated.</p>':'<p class="field-note">Measures beam radius and irradiance at this position.</p>'}</div><div class="inspector-section"><h4>At this plane <span class="green-dot"></span></h4><div class="spec-row"><span>Beam radius</span><b>${planeRadius(c.x).toFixed(3)} mm</b></div><div class="spec-row"><span>Wavelength</span><b>${state.wavelength} nm</b></div></div><div class="component-actions">${c.brand==='Thorlabs'?`<a href="https://www.thorlabs.com/search/thorsearch.cfm?search=${encodeURIComponent(c.part)}" target="_blank" rel="noopener">Find manufacturer part ↗</a>`:''}<button id="duplicate">⧉ Duplicate component</button><button id="delete" class="danger">⌫ Remove from bench</button></div>`;document.querySelectorAll('[data-prop]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return el.reportValidity();checkpoint();c[el.dataset.prop]=+el.value;renderBench();renderResults();renderInspector(c)});$('#wavelength')?.addEventListener('change',e=>{if(!e.target.checkValidity())return e.target.reportValidity();state.wavelength=+e.target.value;renderBench();renderResults()});$('#delete').onclick=()=>{checkpoint();state.items=state.items.filter(x=>x.id!==c.id);state.selected=null;render()};$('#duplicate').onclick=()=>{checkpoint();state.items.push({...c,id:uid++,x:Math.min(c.x+60,780)});render()};$('#upload-image')?.addEventListener('click',()=>$('#image-file').click())}
function field(label,prop,value,unit,min,max){return `<label class="full-field">${label}<div class="input-unit"><input data-prop="${prop}" type="number" step="any" value="${value}" min="${min}" max="${max}"><span>${unit}</span></div></label>`}function planeRadius(x){const s=state.running?simulate():lastResult||simulate();return s.points.reduce((p,c)=>Math.abs(c.x-x)<Math.abs(p.x-x)?c:p).w}
function renderResults(){const s=state.running?simulate():lastResult||simulate();let plot='';if(state.tab==='Beam envelope'){plot=`<svg viewBox="0 0 400 145"><path d="M30 15v110h355" stroke="#424850" fill="none"/>${s.points.length?`<path d="${s.points.map((p,i)=>`${i?'L':'M'}${30+p.x*.44} ${115-Math.min(p.w*12,90)}`).join(' ')}" stroke="#bbf57b" fill="none" stroke-width="2"/>`:''}<text x="170" y="143" fill="#89919c" font-size="11">Position on bench (mm)</text></svg>`}else plot=`<div class="beam-image ${state.tab==='Camera image'?'camera-image':''}" style="--spot:${Math.max(8,Math.min(75,s.w*8))}px;--intensity:${Math.min(1,s.power/5*(s.detector?.exposure||10)/10)}">${state.tab==='Camera image'&&customImage?`<img src="${customImage}" style="filter:blur(${Math.min(s.w/5,8)}px) brightness(${Math.min(2,s.power/5)})" alt="Simulated source image">`:state.tab==='Camera image'&&state.items.some(c=>c.type==='image')?'<div class="test-target">▥ ▥ ▥<br>▤ ▤ ▤<br><small>USAF · TEST TARGET</small></div>':'<span class="crosshair"></span><span class="spot"></span>'}<span class="image-label">${state.tab==='Camera image'?'MONO · APPROXIMATION':'NORMALIZED IRRADIANCE'}</span></div>`;let curve=Array.from({length:100},(_,i)=>`${i?'L':'M'}${20+i*2.8},${100-Math.exp(-2*((i-50)/20)**2)*80}`).join(' ');$('#results-body').innerHTML=`<div class="visual-result">${plot}</div><div class="profile-chart"><div class="chart-label">${state.mode==='Fourier optics'?'Gaussian field intensity':'Horizontal profile'} <span>1/e²</span></div><svg viewBox="0 0 315 125"><path d="M20 20h280M20 60h280M20 100h280" stroke="#363c44" stroke-dasharray="3 4"/><path d="${curve}L297 100H20Z" fill="#bafa7410"/><path d="${curve}" fill="none" stroke="#bafa74" stroke-width="2"/><text x="20" y="120" fill="#929aa5" font-size="11">−${(s.w*2).toFixed(1)}</text><text x="158" y="120" fill="#929aa5" font-size="11">0</text><text x="265" y="120" fill="#929aa5" font-size="11">${(s.w*2).toFixed(1)} mm</text></svg></div><div class="metrics"><div><span>Beam diameter <small>1/e²</small></span><strong>${(s.w*2).toFixed(2)} <small>mm</small></strong></div><div><span>Expansion</span><strong>${s.mag.toFixed(2)}<small>×</small></strong></div><div><span>Optical power</span><strong>${s.power.toFixed(2)} <small>mW</small></strong></div><div><span>Transmission</span><strong>${(100*s.power/(s.source?.power||5)).toFixed(1)}<small>%</small></strong></div></div>`}
function add(i,x){checkpoint();let c={...catalog[i],id:uid++,x:x||Math.min(780,100+state.items.length*90),y:245};state.items.push(c);state.selected=c.id;render();toast(c.name+' added to bench')}
function download(name,data,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-heading"><h2>${title}</h2><button id="close-modal" aria-label="Close">×</button></div>${body}`;$('#modal').showModal();$('#close-modal').onclick=()=>{$('#modal').close();state.page='bench';const hidden=$('#hidden-inspector-body');if(hidden){$('#modal-content').innerHTML='';hidden.id='inspector-body'}document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page==='bench'))}}
function bind(){document.querySelectorAll('[data-category]').forEach(e=>e.onclick=()=>{state.category=e.dataset.category;render()});$('#search').oninput=e=>{state.query=e.target.value;renderCatalog()};$('#run').onclick=()=>{state.running=!state.running;render()};$('#mode').onchange=e=>{state.mode=e.target.value;render();if(state.mode==='Fourier optics')toast('Gaussian analytical field approximation; general FFT propagation is not implemented.')};$('#undo').onclick=()=>{if(state.undo.length){state.items=JSON.parse(state.undo.pop());render()}else toast('No changes to undo')};$('#grid').onclick=()=>{state.grid=!state.grid;render()};$('#zoomin').onclick=()=>{state.zoom=Math.min(1.8,state.zoom+.1);render()};$('#zoomout').onclick=()=>{state.zoom=Math.max(.6,state.zoom-.1);render()};$('#fit').onclick=()=>{state.zoom=1;render()};$('#rename').onclick=()=>{modal('Rename experiment','<label class="full-field">Experiment name<input id="new-name" maxlength="80" value="'+escapeHtml(state.title)+'"></label><button class="run" id="confirm-name">Save name</button>');$('#confirm-name').onclick=()=>{state.title=$('#new-name').value.trim()||state.title;render()}};$('#save').onclick=()=>{download('optibench-project.json',JSON.stringify({version:1,title:state.title,items:state.items,wavelength:state.wavelength},null,2),'application/json');toast('Project saved to a JSON file')};$('#load').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{try{const p=JSON.parse(await e.target.files[0].text());if(p.version!==1||!Array.isArray(p.items)||p.items.length>100||p.items.some(c=>!catalog.some(t=>t.type===c.type)&&c.type!=='image'||!Number.isFinite(c.x)||c.x<0||c.x>820||typeof c.name!=='string'||typeof c.part!=='string'||typeof c.brand!=='string'))throw Error();checkpoint();state.items=p.items.map(c=>({...c,y:245,id:uid++}));state.title=String(p.title||'Imported experiment');state.wavelength=Math.max(200,Math.min(2000,Number(p.wavelength)||532));state.selected=null;render();toast('Project loaded')}catch{toast('Unable to load: choose a valid OptiBench project.')}};$('#image-file').onchange=e=>{const f=e.target.files[0];if(f){if(customImage)URL.revokeObjectURL(customImage);customImage=URL.createObjectURL(f);state.tab='Camera image';render();toast('Source image loaded for approximate detector preview')}};document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{state.tab=e.dataset.tab;render()});$('#bench').ondragover=e=>e.preventDefault();$('#bench').ondrop=e=>{e.preventDefault();let i=+e.dataTransfer.getData('text/plain');if(catalog[i])add(i,Math.round((e.clientX-$('#bench').getBoundingClientRect().left)/$('#bench').getBoundingClientRect().width*820))};$('#help').onclick=showHelp;document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{state.page=e.dataset.page;if(state.page==='bench'){render();return}if(state.page==='library'){state.query='';state.category='All';render();if(innerWidth<=650){modal('Component library','<div id="mobile-catalog"></div>');$('#mobile-catalog').innerHTML=$('#catalog').innerHTML;$('#mobile-catalog').querySelectorAll('[data-add]').forEach(el=>el.onclick=()=>add(+el.dataset.add))}else $('#search').focus();return}if(state.page==='experiments')showTemplates();if(state.page==='analysis')showAnalysis();if(state.page==='bom')showParts()})}
function showTemplates(){modal('Experiment templates',`<p class="modal-intro">Start with an optical arrangement, then make it your own.</p><div class="template-grid">${[['expander','01','Keplerian beam expander','Two positive lenses · 4× nominal expansion'],['focus','02','Laser focusing','Gaussian source · 200 mm focusing lens'],['imaging','03','4f image relay','Image source · spatial aperture · camera']].map(([k,n,t,d])=>`<button data-preset="${k}"><span>${n} <b>→</b></span><h3>${t}</h3><p>${d}</p></button>`).join('')}</div>`);document.querySelectorAll('[data-preset]').forEach(e=>e.onclick=()=>{checkpoint();state.items=structuredClone(presets[e.dataset.preset]).map(c=>({...c,id:uid++,y:245}));state.title=({expander:'Keplerian beam expander',focus:'Laser focusing',imaging:'4f image relay'})[e.dataset.preset];state.selected=state.items[1].id;state.page='bench';state.tab=e.dataset.preset==='imaging'?'Camera image':'Profile';render()})}
function showParts(){modal('Bill of materials',`<p class="modal-intro">Your current bench · ${state.items.length} components. Reference parts must be verified with the manufacturer.</p><table><thead><tr><th>Component</th><th>Part</th><th>Manufacturer</th></tr></thead><tbody>${state.items.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.part)}</td><td>${escapeHtml(c.brand)}</td></tr>`).join('')}</tbody></table><button id="export-bom" class="run">↧ Export CSV</button>`);$('#export-bom').onclick=()=>download('optibench-parts.csv','Component,Part,Manufacturer\n'+state.items.map(c=>[c.name,c.part,c.brand].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv')}
function showAnalysis(){modal('Tolerance analysis',`<p class="modal-intro">Monte Carlo sampling of axial position and focal length. 200 trials using the paraxial Gaussian model.</p><div class="two-fields"><label>Position tolerance (± mm)<input id="tol-position" type="number" min="0" max="20" step="0.1" value="0.5"></label><label>Focal length tolerance (± %)<input id="tol-focal" type="number" min="0" max="20" step="0.1" value="1"></label></div><button id="monte" class="run">▶ Run 200 trials</button><div id="monte-result"></div>`);$('#monte').onclick=()=>{let p=+$('#tol-position').value,f=+$('#tol-focal').value;if(!Number.isFinite(p+f)||p<0||f<0||p>20||f>20)return toast('Use tolerances between 0 and 20.');let values=Array.from({length:200},()=>simulate(state.items.map(c=>({...c,x:c.x+(Math.random()*2-1)*p,f:c.f?c.f*(1+(Math.random()*2-1)*f/100):0}))).w*2).sort((a,b)=>a-b);let mean=values.reduce((a,b)=>a+b,0)/values.length;$('#monte-result').innerHTML=`<div class="analysis-stats"><div><small>Mean diameter</small><strong>${mean.toFixed(3)} mm</strong></div><div><small>5th–95th percentile</small><strong>${values[10].toFixed(3)}–${values[189].toFixed(3)} mm</strong></div></div><p class="modal-intro">Uniform independent variations. Excludes tilt, decenter, surface errors, and manufacturing correlations.</p>`}}
function showHelp(){modal('Your optical workspace','<div class="guide"><h3>Build on the bench</h3><p>Click a library component or drag it onto the table. Drag components horizontally and edit precise positions in the inspector.</p><h3>Inspect the field</h3><p>Gaussian mode propagates the complex beam parameter through ideal thin lenses. Geometrical mode draws paraxial marginal rays. Fourier mode currently displays the analytical Gaussian field only.</p><h3>Save and explore</h3><p>Save projects as local JSON files, export your parts list, load experiment templates, or run a position and focal-length tolerance analysis.</p><h3>Model boundaries</h3><p>All components are centered on one axis. Lens aberrations, polarization, folded paths, measured coatings and calibrated sensor noise are not yet modeled. Image previews are illustrative, not a calibrated imaging simulation. Commercial part labels are reference entries, not a verified catalog.</p></div>')}
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Delete'&&!['INPUT','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){$('#delete')?.click()}});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_optical_bench',description:'Read the current optical components and paraxial Gaussian detector results.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object');const s=simulate();return {title:state.title,components:state.items,beamDiameterMm:s.w*2,powerMw:s.power,model:'Paraxial Gaussian thin-lens approximation'}}},{name:'set_component_position',description:'Move a component along the optical axis and update the visible simulation.',inputSchema:{type:'object',properties:{componentId:{type:'number'},xMm:{type:'number',minimum:40,maximum:780}},required:['componentId','xMm'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isFinite(input.xMm)||input.xMm<40||input.xMm>780||Object.keys(input).some(k=>!['componentId','xMm'].includes(k)))throw Error('Invalid position');const c=state.items.find(c=>c.id===input.componentId);if(!c)throw Error('Component not found');checkpoint();c.x=input.xMm;state.selected=c.id;render();return {componentId:c.id,xMm:c.x,beamDiameterMm:simulate().w*2}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
